/** @type {import('tailwindcss').Config} */

// PREMA design tokens.
// Token *names* follow the "Warm Editorial Intent" design system (DESIGN.md) that the
// exported screens were built with; the *values* are tuned to the live app palette
// (soft sky canvas, navy #2C496A type, sky-blue #74B4F2 accent, coral #FF6B8B CTA)
// so every screen matches Discover / Match Detail / Profile.
// Sizes are in px on purpose: NativeWind resolves 1rem = 14px, not 16px.

// Colours come from the colour system (src/theme/palette.json, generated by
// tools/colour/generate_palette.py), so NativeWind classes and the TS tokens in
// src/theme/tokens.ts can't drift apart. See docs/colour-system.md (Phase 3).
const palette = require('./src/theme/palette.json');

// A ramp as a Tailwind colour: `bg-brand` is the brand colour itself, and
// `bg-brand-50` … `bg-brand-950` are its shades.
const ramp = (name, base) => ({ DEFAULT: palette[name][base], ...palette[name] });
const { primary: P, accent: A, brand: B, neutral: N } = palette;
const white = '#FFFFFF';

const colors = {
  // Palette ramps. DEFAULT = the original brand colour, unchanged.
  primary: ramp('primary', '700'), // navy #2C496A
  accent: ramp('accent', '300'), // sky blue #74B4F2
  brand: ramp('brand', '300'), // pink #FF6B8B
  neutral: ramp('neutral', '400'), // grey #8892A3
  danger: ramp('danger', '500'), // red #D64545
  success: ramp('success', '300'), // green #3BB273

  // Names from the original design mockups that screens still use
  // (SendIntentionalNote, Discover). Prefer the ramps above in new code; these
  // go away as screens migrate (Phase 4).
  //
  // Text and accent names point at the palette shade used for the same role in
  // src/theme/tokens.ts:
  'on-surface': P['700'],
  'on-surface-variant': P['500'], // was #62758C
  'primary-container': P['800'], // was #1A2E44, = colors.background.inverse
  'on-primary': white,
  'on-primary-container': P['200'], // was #A9C3DD
  // Was #4A90D9. accent-500 rather than the nearest (400) so this blue text gets
  // easier to read, not harder: 4.23:1 on white vs 3.34 before (400 would be 3.01).
  secondary: A['500'],
  'on-secondary': white,
  'on-secondary-container': A['600'], // was #2C5F8F
  //
  // Surface names keep their exact original values for now. These pale layers
  // are 1–8% lightness apart, and the palette has no shade between 50 and 100,
  // so mapping them would make panels vanish into the card or page behind
  // them. Pending a decision on finer light stops (docs/colour-system.md).
  surface: '#F1F7FD',
  'surface-variant': '#E3EDF7',
  'surface-container-lowest': white,
  'surface-container-low': '#F6F9FC',
  'surface-container': '#EDF3F9',
  'surface-container-high': '#E6EEF6',
  'surface-container-highest': '#DDE7F1',
  'secondary-container': '#DCEBFA',
  coral: B['300'], // #FF6B8B
};

const type = (size, lineHeight, weight, tracking) => [
  `${size}px`,
  { lineHeight: `${lineHeight}px`, fontWeight: weight, letterSpacing: `${tracking}px` },
];

module.exports = {
  content: [
    "./app/**/*.{js,jsx,ts,tsx}",
    "./components/**/*.{js,jsx,ts,tsx}",
    "./src/**/*.{js,jsx,ts,tsx}"
  ],
  presets: [require("nativewind/preset")],
  theme: {
    extend: {
      colors,
      fontSize: {
        'headline-display': type(40, 48, '700', -1.2),
        'headline-lg': type(32, 38, '700', -0.64),
        'headline-lg-mobile': type(26, 32, '700', -0.52),
        'headline-md': type(22, 28, '600', -0.33),
        'headline-sm': type(18, 24, '600', -0.18),
        'body-lg': type(16, 24, '400', 0),
        'body-md': type(14, 21, '400', 0.07),
        'body-sm': type(13, 18, '400', 0.13),
        'label-lg': type(15, 20, '600', 0.15),
        'label-md': type(13, 18, '600', 0.26),
        'label-sm': type(11, 14, '700', 0.44),
      },
      spacing: {
        'space-2': '2px',
        'space-4': '4px',
        'space-6': '6px',
        'space-8': '8px',
        'space-12': '12px',
        'space-16': '16px',
        'space-20': '20px',
        'space-24': '24px',
        'space-32': '32px',
        'space-40': '40px',
        'space-48': '48px',
        'gutter-mobile': '16px',
        'margin-mobile': '20px',
        'margin-tablet': '32px',
      },
      borderRadius: {
        sm: '4px',
        DEFAULT: '8px',
        md: '12px',
        lg: '16px',
        xl: '24px',
        '2xl': '24px',
        '3xl': '32px',
      },
    },
  },
  plugins: [],
};
